-- ------------------------------------------------------------
-- Table: master_achiever_queue_filter   (achiever_queue_filter)
--
-- The filter dropdown on Admin > Achiever Review. It was a hardcoded
-- QUEUE_FILTERS array in AdminAchieverLifecycle.jsx.
--
-- NOTE for whoever edits these rows: `value` is not free text. Each one is a
-- scope the queue query already implements ('all', 'everyone', 'pending',
-- 'decision', 'probation'). Editing a label, reordering, or switching a row
-- off all work from here. Inventing a NEW value does not create filtering
-- behaviour on its own — the queue would return nothing for it until the
-- backend learns that scope. Add labels freely; add values with code.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `master_achiever_queue_filter` (
  `id` CHAR(36) NOT NULL,
  `value` VARCHAR(100) NOT NULL,
  `label` VARCHAR(150) NOT NULL,
  `sort_order` INT NULL DEFAULT 0,
  `is_active` TINYINT(1) NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` CHAR(36) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_master_achiever_queue_filter_value` (`value`),
  KEY `ix_master_achiever_queue_filter_active` (`is_active`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
